add_shortcode( 'product_attributes_table', 'perfectpixel_product_attributes_shortcode' );

function perfectpixel_product_attributes_shortcode( $atts ) {
	$atts    = shortcode_atts( array( 'id' => 0 ), $atts );
	$product = wc_get_product( absint( $atts['id'] ) ? absint( $atts['id'] ) : get_the_ID() );
	if ( ! $product || ! function_exists( 'wc_display_product_attributes' ) ) {
		return '';
	}
	ob_start();
	wc_display_product_attributes( $product );
	return '<div class="woocommerce perfectpixel-attributes-table">' . ob_get_clean() . '</div>';
}
